'use strict';

function normalizeSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new TypeError('sku must be a non-empty string');
  }
  return sku.trim();
}

function copyRecord(record) {
  return {
    sku: record.sku,
    description: record.description,
    quantity: record.quantity
  };
}

function validateRecord(record) {
  if (record === null || typeof record !== 'object' || Array.isArray(record)) {
    throw new TypeError('record must be an object');
  }
  const sku = normalizeSku(record.sku);
  if (typeof record.description !== 'string' || record.description.trim() === '') {
    throw new TypeError('description must be a non-empty string');
  }
  if (!Number.isInteger(record.quantity) || record.quantity < 0) {
    throw new TypeError('quantity must be a non-negative integer');
  }
  return { sku, description: record.description.trim(), quantity: record.quantity };
}

class PartsCatalog {
  constructor(initialRecords = []) {
    if (!Array.isArray(initialRecords)) {
      throw new TypeError('initialRecords must be an array');
    }
    this._records = new Map();
    for (const record of initialRecords) this.add(record);
  }

  add(record) {
    const normalized = validateRecord(record);
    if (this._records.has(normalized.sku)) throw new Error('duplicate sku');
    this._records.set(normalized.sku, normalized);
    return normalized;
  }

  get(sku) {
    const key = normalizeSku(sku);
    const record = this._records.get(key);
    return record ? copyRecord(record) : null;
  }

  list() {
    return Array.from(this._records.values(), copyRecord);
  }

  update(sku, patch) {
    const key = normalizeSku(sku);
    if (patch === null || typeof patch !== 'object' || Array.isArray(patch)) {
      throw new TypeError('patch must be an object');
    }
    const keys = Object.keys(patch);
    if (keys.some((name) => name !== 'description' && name !== 'quantity')) {
      throw new TypeError('patch has an unknown property');
    }
    if (Object.prototype.hasOwnProperty.call(patch, 'description') &&
        (typeof patch.description !== 'string' || patch.description.trim() === '')) {
      throw new TypeError('invalid description');
    }
    if (Object.prototype.hasOwnProperty.call(patch, 'quantity') &&
        (!Number.isInteger(patch.quantity) || patch.quantity < 0)) {
      throw new TypeError('invalid quantity');
    }

    const current = this._records.get(key);
    if (!current) return null;
    const updated = {
      sku: current.sku,
      description: Object.prototype.hasOwnProperty.call(patch, 'description')
        ? patch.description.trim() : current.description,
      quantity: Object.prototype.hasOwnProperty.call(patch, 'quantity')
        ? patch.quantity : current.quantity
    };
    this._records.set(key, updated);
    return copyRecord(updated);
  }

  remove(sku) {
    return this._records.delete(normalizeSku(sku));
  }
}

module.exports = { PartsCatalog };

