'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['PartsCatalog']);
assert.strictEqual(typeof api.PartsCatalog, 'function');
const { PartsCatalog } = api;

assert.throws(() => new PartsCatalog(null), TypeError);
assert.throws(() => new PartsCatalog({}), TypeError);
assert.throws(() => new PartsCatalog([
  { sku: ' A ', description: 'one', quantity: 1 },
  { sku: 'A', description: 'two', quantity: 2 }
]), Error);

const initial = [
  { sku: ' A-1 ', description: ' First part ', quantity: 2 },
  { sku: 'a-1', description: 'Case-sensitive', quantity: 0 }
];
const snapshot = JSON.parse(JSON.stringify(initial));
const catalog = new PartsCatalog(initial);
assert.deepStrictEqual(initial, snapshot);
assert.deepStrictEqual(catalog.list(), [
  { sku: 'A-1', description: 'First part', quantity: 2 },
  { sku: 'a-1', description: 'Case-sensitive', quantity: 0 }
]);

initial[0].description = 'Changed outside';
assert.strictEqual(catalog.get(' A-1 ').description, 'First part');
const got = catalog.get('A-1');
got.description = 'Changed copy';
assert.strictEqual(catalog.get('A-1').description, 'First part');
assert.notStrictEqual(catalog.get('A-1'), catalog.get('A-1'));
assert.strictEqual(catalog.get('missing'), null);

const callerRecord = { sku: ' B-2 ', description: ' Second ', quantity: 3 };
const added = catalog.add(callerRecord);
assert.deepStrictEqual(added, { sku: 'B-2', description: 'Second', quantity: 3 });
assert.notStrictEqual(added, callerRecord);
callerRecord.description = 'Caller changed';
added.quantity = 999;
assert.deepStrictEqual(catalog.get('B-2'), {
  sku: 'B-2', description: 'Second', quantity: 3
});
assert.throws(() => catalog.add({ sku: ' B-2 ', description: 'Duplicate', quantity: 1 }), Error);

const updated = catalog.update(' A-1 ', { description: ' Updated ', quantity: 7 });
assert.deepStrictEqual(updated, { sku: 'A-1', description: 'Updated', quantity: 7 });
updated.description = 'Changed copy';
assert.deepStrictEqual(catalog.list().map((record) => record.sku), ['A-1', 'a-1', 'B-2']);
assert.strictEqual(catalog.get('A-1').description, 'Updated');
assert.deepStrictEqual(catalog.update('A-1', {}), {
  sku: 'A-1', description: 'Updated', quantity: 7
});
assert.strictEqual(catalog.update('absent', { quantity: 1 }), null);

const listed = catalog.list();
listed.reverse();
listed[0].quantity = 1000;
assert.deepStrictEqual(catalog.list().map((record) => record.sku), ['A-1', 'a-1', 'B-2']);
assert.strictEqual(catalog.get('B-2').quantity, 3);
assert.strictEqual(catalog.remove(' a-1 '), true);
assert.strictEqual(catalog.remove('a-1'), false);
assert.deepStrictEqual(catalog.list().map((record) => record.sku), ['A-1', 'B-2']);

const badRecords = [null, [], {},
  { sku: '', description: 'D', quantity: 0 },
  { sku: '  ', description: 'D', quantity: 0 },
  { sku: 1, description: 'D', quantity: 0 },
  { sku: 'S', description: '', quantity: 0 },
  { sku: 'S', description: '  ', quantity: 0 },
  { sku: 'S', description: 1, quantity: 0 },
  { sku: 'S', description: 'D', quantity: -1 },
  { sku: 'S', description: 'D', quantity: 1.5 },
  { sku: 'S', description: 'D', quantity: '1' }
];
for (const record of badRecords) {
  assert.throws(() => new PartsCatalog([record]), TypeError);
}

for (const badSku of [null, undefined, 1, '', '   ']) {
  assert.throws(() => catalog.get(badSku), TypeError);
  assert.throws(() => catalog.update(badSku, {}), TypeError);
  assert.throws(() => catalog.remove(badSku), TypeError);
}
for (const badPatch of [null, [], 1, 'x']) {
  assert.throws(() => catalog.update('absent', badPatch), TypeError);
}
assert.throws(() => catalog.update('absent', { extra: true }), TypeError);
assert.throws(() => catalog.update('A-1', { description: '' }), TypeError);
assert.throws(() => catalog.update('A-1', { quantity: -1 }), TypeError);
assert.deepStrictEqual(catalog.get('A-1'), {
  sku: 'A-1', description: 'Updated', quantity: 7
});

